begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('4d400000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.cmd(n integer,op text,payload jsonb) returns jsonb language sql as $$select public.platform_team_command(pg_temp.id(n),op,payload)$$;
create temp table saved(k text primary key,v text);
grant all on saved to authenticated;
insert into auth.users(id,aud,role,email,confirmed_at) values
 (pg_temp.id(1),'authenticated','authenticated','team-admin@example.invalid',now()),
 (pg_temp.id(2),'authenticated','authenticated','team-new@example.invalid',null),
 (pg_temp.id(3),'authenticated','authenticated','team-existing@example.invalid',now()),
 (pg_temp.id(4),'authenticated','authenticated','team-sandbox-only@example.invalid',now());
insert into public.persons(id,auth_user_id,display_name) values(pg_temp.id(11),pg_temp.id(1),'Synthetic team admin'),(pg_temp.id(13),pg_temp.id(3),'Existing name'),(pg_temp.id(14),pg_temp.id(4),'Sandbox only');
insert into pikas_private.platform_memberships(person_id,role_code) values(pg_temp.id(11),'platform_admin'),(pg_temp.id(14),'platform_sandbox_operator');
insert into pikas_private.platform_team_handles(person_id) values(pg_temp.id(11)),(pg_temp.id(14));
select ok(not has_table_privilege('authenticated','pikas_private.platform_team_intents','select'),'Intent storage private');
select ok(not has_table_privilege('authenticated','pikas_private.platform_team_handles','select'),'Handles private');
select ok(not has_function_privilege('anon','public.platform_team_command(uuid,text,jsonb)','execute'),'Anonymous command unavailable');
select ok(not has_function_privilege('service_role','public.platform_team_command(uuid,text,jsonb)','execute'),'Service role cannot bypass');
select is((select count(*) from pikas_private.platform_role_capabilities where role_code='platform_admin' and capability='platform:sandbox:pov:enter'),0::bigint,'Admin never bundles sandbox entry');
select set_config('request.jwt.claim.sub','',true);set local role authenticated;
select throws_ok($$select public.platform_team_read()$$,'42501',null,'Unauthenticated read denied');
reset role;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002001',true);set local role authenticated;
select throws_ok($$select public.platform_team_read()$$,'42501',null,'Tenant-only admin read denied');
select throws_ok($$select pg_temp.cmd(100,'prepare','{"name":"X","email":"x@example.invalid","demo":true}')$$,'42501',null,'Tenant-only mutation denied');
reset role;select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);set local role authenticated;
select throws_ok($$select public.platform_team_read()$$,'42501',null,'Sandbox-only cannot administer team');
reset role;select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);set local role authenticated;
select lives_ok($$select public.platform_team_read()$$,'Platform admin reads team');
select ok(not(public.platform_team_read()::text ~ '(auth_user_id|person_id|membership_id|capabilities|token_hash)'),'Projection excludes security IDs/metadata');
select throws_ok($$select pg_temp.cmd(101,'prepare','{"name":"X","email":"x@example.invalid","demo":true,"auth_id":"4d400000-0000-4000-8000-000000000002"}')$$,'22023',null,'Arbitrary Auth field denied');
select throws_ok($$select pg_temp.cmd(102,'deactivate','{}')$$,'22023',null,'Platform removal unavailable; last admin preserved');
select lives_ok($$select pg_temp.cmd(103,'prepare','{"name":"New operator","email":"team-new@example.invalid","demo":true}')$$,'Prepare succeeds');
select lives_ok($$select pg_temp.cmd(103,'prepare','{"name":"New operator","email":"team-new@example.invalid","demo":true}')$$,'Prepare replay succeeds');
reset role;
select is((select count(*) from pikas_private.platform_team_intents where email_key='team-new@example.invalid'),1::bigint,'One prepared intent');
select is((select count(*) from public.persons where auth_user_id=pg_temp.id(2)),0::bigint,'Prepare creates no Person');
select is((select count(*) from pikas_private.platform_memberships),2::bigint,'Prepare grants no authority');
insert into saved select 'new',handle from pikas_private.platform_team_intents where email_key='team-new@example.invalid';
set local role authenticated;
select throws_ok($$select pg_temp.cmd(104,'complete',jsonb_build_object('handle',(select v from saved where k='new')))$$,'23514','confirmed_identity_pending','Unconfirmed identity cannot complete');
reset role;update auth.users set confirmed_at=now() where id=pg_temp.id(2);set local role authenticated;
select lives_ok($$select pg_temp.cmd(104,'complete',jsonb_build_object('handle',(select v from saved where k='new')))$$,'Confirmed identity completes');
select lives_ok($$select pg_temp.cmd(104,'complete',jsonb_build_object('handle',(select v from saved where k='new')))$$,'Completion replay safe');
select throws_ok($$select pg_temp.cmd(105,'complete',jsonb_build_object('handle',(select v from saved where k='new')))$$,'23514',null,'Different-key completion cannot duplicate grants');
reset role;
select is((select count(*) from public.persons where auth_user_id=pg_temp.id(2)),1::bigint,'Exactly one Person');
select is((select count(*) from pikas_private.platform_memberships m join public.persons p on p.id=m.person_id where p.auth_user_id=pg_temp.id(2)),2::bigint,'Exactly two deliberately selected roles');
select is((select count(*) from pikas_private.platform_audit_events where request_id=pg_temp.id(104) and actor_person_id=pg_temp.id(11) and actor_auth_user_id=pg_temp.id(1) and action='team_complete'),1::bigint,'Real actor audited once');
insert into saved select 'operator',h.handle from pikas_private.platform_team_handles h join public.persons p on p.id=h.person_id where p.auth_user_id=pg_temp.id(2);
select is((select count(*) from public.cafeteria_memberships m join public.persons p on p.id=m.person_id where p.auth_user_id=pg_temp.id(2)),0::bigint,'No cafeteria or cashier membership');
select is((select count(*) from public.account_memberships m join public.persons p on p.id=m.person_id where p.auth_user_id=pg_temp.id(2)),0::bigint,'No account membership');
select is((select count(*) from public.school_memberships m join public.persons p on p.id=m.person_id where p.auth_user_id=pg_temp.id(2)),0::bigint,'No school membership');
set local role authenticated;
select lives_ok($$select pg_temp.cmd(106,'demo',jsonb_build_object('handle',(select v from saved where k='operator'),'enabled',false))$$,'Disable demo only');
reset role;
select is((select count(*) from pikas_private.platform_memberships m join public.persons p on p.id=m.person_id where p.auth_user_id=pg_temp.id(2) and m.role_code='platform_admin' and m.status='active'),1::bigint,'Admin remains active after demo removal');
select is((select count(*) from pikas_private.platform_memberships m join public.persons p on p.id=m.person_id where p.auth_user_id=pg_temp.id(2) and m.role_code='platform_sandbox_operator' and m.status='active'),0::bigint,'Demo removed');
set local role authenticated;
select lives_ok($$select pg_temp.cmd(107,'demo',jsonb_build_object('handle',(select v from saved where k='operator'),'enabled',true))$$,'Demo can be granted again through a new membership');
select throws_ok($$select pg_temp.cmd(108,'demo',jsonb_build_object('handle',repeat('f',32),'enabled',true))$$,'42501',null,'Unknown/customer handle denied');
select lives_ok($$select pg_temp.cmd(109,'prepare','{"name":"Do not overwrite","email":"team-existing@example.invalid","demo":false}')$$,'Existing unprivileged linked Person can be prepared');
reset role;insert into saved select 'existing',handle from pikas_private.platform_team_intents where email_key='team-existing@example.invalid';set local role authenticated;
select lives_ok($$select pg_temp.cmd(110,'complete',jsonb_build_object('handle',(select v from saved where k='existing')))$$,'Existing eligible link reused safely');
reset role;
select is((select display_name from public.persons where id=pg_temp.id(13)),'Existing name','Existing Person name/link not replaced');
select is((select count(*) from pikas_private.platform_memberships where person_id=pg_temp.id(13) and role_code='platform_sandbox_operator'),0::bigint,'Demo false grants admin only');
update auth.users set confirmed_at=now() where id='00000000-0000-0000-0000-000000002001';set local role authenticated;
select lives_ok($$select pg_temp.cmd(111,'prepare','{"name":"Tenant","email":"foundation-1@example.invalid","demo":true}')$$,'Prepare still grants nothing for customer email');
reset role;insert into saved select 'tenant',handle from pikas_private.platform_team_intents where email_key='foundation-1@example.invalid';set local role authenticated;
select throws_ok($$select pg_temp.cmd(112,'complete',jsonb_build_object('handle',(select v from saved where k='tenant')))$$,'42501',null,'Customer identity cannot be converted');
select throws_ok($$select pg_temp.cmd(103,'prepare','{"name":"Different","email":"team-new@example.invalid","demo":true}')$$,'23505',null,'Key cannot be reused with changed payload');
-- Existing platform links and inactive Persons are never silently converted/reactivated.
select lives_ok($$select pg_temp.cmd(113,'prepare','{"name":"Existing operator","email":"team-existing@example.invalid","demo":true}')$$,'Preparation alone cannot replace an operator');
reset role;insert into saved select 'existing-admin',handle from pikas_private.platform_team_intents where email_key='team-existing@example.invalid' and status='pending';set local role authenticated;
select throws_ok($$select pg_temp.cmd(114,'complete',jsonb_build_object('handle',(select v from saved where k='existing-admin')))$$,'42501',null,'Existing platform identity cannot be replaced or reactivated by onboarding');
reset role;
insert into auth.users(id,aud,role,email,confirmed_at) values(pg_temp.id(5),'authenticated','authenticated','team-inactive@example.invalid',now());
insert into public.persons(id,auth_user_id,display_name,status) values(pg_temp.id(15),pg_temp.id(5),'Inactive','inactive');
set local role authenticated;
select lives_ok($$select pg_temp.cmd(115,'prepare','{"name":"Inactive","email":"team-inactive@example.invalid","demo":false}')$$,'Inactive identity preparation grants nothing');
reset role;insert into saved select 'inactive',handle from pikas_private.platform_team_intents where email_key='team-inactive@example.invalid';set local role authenticated;
select throws_ok($$select pg_temp.cmd(116,'complete',jsonb_build_object('handle',(select v from saved where k='inactive')))$$,'23514','active_person_required','Inactive Person cannot complete');
-- Two real operators use one shared synthetic sandbox through the frozen launcher contract.
reset role;
insert into public.accounts(id,code,name,tenant_kind) values(pg_temp.id(50),'TEAM-SANDBOX','Synthetic shared sandbox','sandbox');
insert into public.schools(id,account_id,code,name) values(pg_temp.id(51),pg_temp.id(50),'S','Synthetic sandbox school');
insert into public.school_locations(id,account_id,school_id,code,name) values(pg_temp.id(52),pg_temp.id(50),pg_temp.id(51),'L','Synthetic campus');
insert into public.cafeterias(id,account_id,school_id,school_location_id,code,name) values(pg_temp.id(53),pg_temp.id(50),pg_temp.id(51),pg_temp.id(52),'C','Synthetic cafe');
insert into public.persons(id,display_name) values(pg_temp.id(54),'Synthetic shared cashier');
insert into public.cafeteria_memberships(id,person_id,account_id,school_id,cafeteria_id,role_code) values(pg_temp.id(55),pg_temp.id(54),pg_temp.id(50),pg_temp.id(51),pg_temp.id(53),'pos_cashier');
insert into pikas_private.sandbox_pov_personas(account_id,school_id,cafeteria_id,pov_code,person_id,cafeteria_membership_id) values(pg_temp.id(50),pg_temp.id(51),pg_temp.id(53),'cashier',pg_temp.id(54),pg_temp.id(55));
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);set local role authenticated;
select lives_ok($$select public.platform_enter_sandbox_pov(pg_temp.id(120),pg_temp.id(50),pg_temp.id(53),'cashier')$$,'First operator enters existing shared sandbox');
reset role;insert into pikas_private.platform_memberships(person_id,role_code) values(pg_temp.id(13),'platform_sandbox_operator');select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);set local role authenticated;
select lives_ok($$select public.platform_enter_sandbox_pov(pg_temp.id(121),pg_temp.id(50),pg_temp.id(53),'cashier')$$,'Second operator independently enters same sandbox');
reset role;
select is((select count(*) from pikas_private.sandbox_pov_sessions where account_id=pg_temp.id(50) and status='active'),2::bigint,'Independent POV sessions coexist');
select is((select count(distinct persona_id) from pikas_private.sandbox_pov_sessions where account_id=pg_temp.id(50)),1::bigint,'One shared persona retained');
select is((select count(*) from public.cafeteria_memberships where person_id in (pg_temp.id(13),(select id from public.persons where auth_user_id=pg_temp.id(2)))),0::bigint,'POV does not grant either real operator tenant membership');
update pikas_private.platform_memberships set status='suspended' where person_id=pg_temp.id(11) and role_code='platform_admin';select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);set local role authenticated;
select throws_ok($$select public.platform_team_read()$$,'42501',null,'Revoked platform authority denies read');
select throws_ok($$select pg_temp.cmd(104,'complete',jsonb_build_object('handle',(select v from saved where k='new')))$$,'42501',null,'Recovery cannot bypass revoked authority');
select * from finish();
rollback;
